     "yaku": "is",
     "dhaa": "possessor of",
     "famin": "a mouth",
     "murrin": "bitter",
     "mariidin": "sick",
     "yajid": "finds",
     "murran": "bitter",
     "bihi": "with it",
     "al-maa'a": "the water",
     "al-zulaalaa": "the pure, fresh"
